cat > /tmp/checks-at-base.mjs <<'EOF'
export async function checksAtBase ({ checks, enabled, clone, base, sh, timeoutSeconds, runLines, appendEvent }) {
  if (enabled !== true || !Array.isArray(checks) || checks.length === 0) return []
  let dir
  try {
    dir = clone()
  } catch (e) {
    return []
  }
  let results
  try {
    results = await runLines({
      lines: checks.map((c) => c.cmd), cwd: dir, sh, env: { ULTRA_BASE: base }, timeoutSeconds
    })
  } catch (e) {
    return []
  }
  const out = []
  for (let i = 0; i < results.length; i++) {
    const row = { kind: 'check:line', base: true, cmd: results[i].cmd, exit: results[i].exit, minor: Boolean(checks[i].minor) }
    appendEvent(row)
    out.push(row)
  }
  return out
}
export default { checksAtBase }
EOF
